package zone.moddev.mc.ironagearchitecture.roof;

import java.util.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.BlockPos;
import zone.moddev.mc.ironagearchitecture.block.WindowGeometry;

/** Fixed roof-light kit and precise clipped faces. World access is deliberately absent. */
public final class RoofWindowGeometry {
    private static final Map<Key,RoofMeshes.Mesh> CACHE=Collections.synchronizedMap(new LinkedHashMap<Key,RoofMeshes.Mesh>(128,.75f,true){protected boolean removeEldestEntry(Map.Entry<Key,RoofMeshes.Mesh> e){return size()>2048;}});
    private static final Map<Key,List<AxisAlignedBB>> SWEEPS=Collections.synchronizedMap(new LinkedHashMap<Key,List<AxisAlignedBB>>(32,.75f,true){protected boolean removeEldestEntry(Map.Entry<Key,List<AxisAlignedBB>> e){return size()>256;}});
    private static final class Key{final RoofWindow w;Key(RoofWindow a){w=new RoofWindow("",net.minecraft.util.math.BlockPos.ORIGIN,a.dx,a.dy,a.dz,a.y32,a.slope32,a.style&1,a.joins,a.facing,a.vertical,a.right,a.open,false).rise(a.rise32);}public int hashCode(){return w.geometryHash();}public boolean equals(Object o){return o instanceof Key&&w.geometryEquals(((Key)o).w);}}
    private RoofWindowGeometry(){}
    public static Map<Long,RoofCell> layout(UUID plan,Map<Long,RoofCell> base,Collection<RoofWindow> units){Map<Long,List<RoofPart>> parts=new TreeMap<>();Map<Long,List<RoofWindow>> windows=new TreeMap<>();for(Map.Entry<Long,RoofCell> e:base.entrySet()){List<RoofPart> ps=new ArrayList<>();for(RoofPart p:e.getValue().parts)if(p.kind!=RoofPart.WINDOW)ps.add(p);if(!ps.isEmpty())parts.put(e.getKey(),ps);}for(RoofWindow original:units){RoofWindow w=original.slice(original.owner);for(BlockPos at:candidates(w)){RoofWindow slice=w.slice(at);if(mesh(slice).faces.isEmpty())continue;parts.computeIfAbsent(at.toLong(),k->new ArrayList<>()).add(new RoofPart(w.id,w.owner,RoofPart.WINDOW,w.style,new int[0]));windows.computeIfAbsent(at.toLong(),k->new ArrayList<>()).add(slice);}}Map<Long,RoofCell> out=new TreeMap<>();for(long key:parts.keySet())out.put(key,new RoofCell(plan,BlockPos.fromLong(key),parts.get(key),windows.getOrDefault(key,Collections.emptyList())));return out;}
    public static List<BlockPos> sweepCandidates(RoofWindow w){Set<BlockPos> cells=new LinkedHashSet<>();cells.addAll(candidates(w.state(false,w.powered)));cells.addAll(candidates(w.state(true,w.powered)));if(!w.vertical)for(BlockPos p:new ArrayList<>(cells))for(net.minecraft.util.EnumFacing face:net.minecraft.util.EnumFacing.HORIZONTALS)cells.add(p.offset(face));return new ArrayList<>(cells);}
    public static List<AxisAlignedBB> sweepBoxes(RoofWindow w){Key key=new Key(w.state(false,false));List<AxisAlignedBB> cached=SWEEPS.get(key);if(cached!=null)return cached;List<AxisAlignedBB> boxes=new ArrayList<>();if(w.vertical){AxisAlignedBB b=WindowGeometry.sweep(w.right,w.facing).offset(w.dx,w.dy,w.dz);addBox(boxes,b.expand(.004,0,.004));}else for(int angle=0;angle<=45;angle++)sliced(boxes,w,.094,.906,.094,.906,.106,.15,true,angle);cached=Collections.unmodifiableList(boxes);SWEEPS.put(key,cached);return cached;}
    public static List<AxisAlignedBB> movingBoxes(RoofWindow w){List<AxisAlignedBB> out=new ArrayList<>();if(w.vertical){for(boolean proxy:new boolean[]{false,true})for(AxisAlignedBB b:WindowGeometry.movingBoxes(w.right,w.open,w.facing,w.joins,proxy))addBox(out,b.offset(w.dx+(proxy?w.facing.getFrontOffsetX():0),w.dy,w.dz+(proxy?w.facing.getFrontOffsetZ():0)));}else sliced(out,w,.094,.906,.094,.906,.106,.15,true);return out;}
    public static List<net.minecraft.util.math.BlockPos> candidates(RoofWindow source){RoofWindow w=source.slice(source.owner);List<net.minecraft.util.math.BlockPos> out=new ArrayList<>();if(w.vertical){out.add(w.owner);if(w.open)out.add(w.owner.offset(w.facing));return out;}double[] lo={100,100,100},hi={-100,-100,-100};for(boolean moving:new boolean[]{false,true})for(double x:new double[]{0,1})for(double y:new double[]{0,1})for(double z:new double[]{0,1}){double[] q=point(w,x,y,z,moving);for(int i=0;i<3;i++){lo[i]=Math.min(lo[i],q[i]);hi[i]=Math.max(hi[i],q[i]);}}for(int x=(int)Math.floor(lo[0]+1e-8);x<Math.ceil(hi[0]-1e-8);x++)for(int y=(int)Math.floor(lo[1]+1e-8);y<Math.ceil(hi[1]-1e-8);y++)for(int z=(int)Math.floor(lo[2]+1e-8);z<Math.ceil(hi[2]-1e-8);z++)out.add(w.owner.add(x,y,z));return out;}
    public static RoofMeshes.Mesh mesh(RoofWindow w){Key key=new Key(w);RoofMeshes.Mesh found=CACHE.get(key);if(found!=null)return found;List<RoofMeshes.Face> faces=new ArrayList<>();List<AxisAlignedBB> boxes=new ArrayList<>();boolean diamond=(w.style&1)==0;
        if(w.vertical){for(boolean proxy:new boolean[]{false,true})for(WindowGeometry.Face face:WindowGeometry.faces(false,diamond,w.right,w.open,w.facing,w.joins,proxy,false)){List<double[]> p=new ArrayList<>();for(double[] v:face.vertices)p.add(new double[]{v[0]/16+w.dx+(proxy?w.facing.getFrontOffsetX():0),v[1]/16+w.dy,v[2]/16+w.dz+(proxy?w.facing.getFrontOffsetZ():0),v[3],v[4]});add(faces,p,face.material.ordinal());}for(boolean proxy:new boolean[]{false,true})for(AxisAlignedBB box:WindowGeometry.boxes(false,w.right,w.open,w.facing,w.joins,proxy,false)){AxisAlignedBB b=box.offset(w.dx+(proxy?w.facing.getFrontOffsetX():0),w.dy,w.dz+(proxy?w.facing.getFrontOffsetZ():0));addBox(boxes,b);}}
        else{
            for(WindowGeometry.Face face:WindowGeometry.roofFaces(diamond)){List<double[]> p=new ArrayList<>();for(double[] v:face.vertices){double[] q=point(w,v[0]/16,v[1]/16,v[2]/16,face.moving);p.add(new double[]{q[0],q[1],q[2],v[3],v[4]});}add(faces,p,face.material.ordinal());}
            // Frame uprights and the filled leaf use narrow slices, not a whole roof-cell box.
            for(double[] x:new double[][]{{0,.094},{.906,1}})sliced(boxes,w,x[0],x[1],0,1,0,1,false);
            for(double[] y:new double[][]{{0,.094},{.906,1}})sliced(boxes,w,.094,.906,y[0],y[1],0,1,false);
            sliced(boxes,w,.094,.906,.094,.906,.106,.15,true);
        }
        found=faces.isEmpty()?RoofMeshes.EMPTY:new RoofMeshes.Mesh(faces,boxes);CACHE.put(key,found);return found;
    }
    private static double[] point(RoofWindow w,double x,double y,double z,boolean moving){return point(w,x,y,z,moving,w.open?45:0);}
    private static double[] point(RoofWindow w,double x,double y,double z,boolean moving,double angle){double slope=w.slope32/32.0,length=Math.sqrt(1+slope*slope),s=y*length,n=(.125-z)*.25;if(moving&&angle!=0){double pivot=.90625*length,a=s-pivot,c=Math.cos(Math.toRadians(angle)),t=Math.sin(Math.toRadians(angle));s=pivot+a*c+n*t;n=-a*t+n*c;}double inward=s/length-n*slope/length,up=s*slope/length+n/length;EnumFacing across=w.facing.rotateY();return new double[]{w.dx+.5+across.getFrontOffsetX()*(x-.5)+w.facing.getFrontOffsetX()*(.5-inward),w.dy+w.y32/32.0+up+w.rise32/32.0*(moving?1:1-Math.max(0,Math.min(1,(z-.1875)/.8125))),w.dz+.5+across.getFrontOffsetZ()*(x-.5)+w.facing.getFrontOffsetZ()*(.5-inward)};}
    private static void sliced(List<AxisAlignedBB> out,RoofWindow w,double x0,double x1,double y0,double y1,double z0,double z1,boolean moving){sliced(out,w,x0,x1,y0,y1,z0,z1,moving,w.open?45:0);}
    private static void sliced(List<AxisAlignedBB> out,RoofWindow w,double x0,double x1,double y0,double y1,double z0,double z1,boolean moving,double angle){for(int zi=0;zi<(moving?1:16);zi++)for(int i=0;i<32;i++){double az=z0+(z1-z0)*zi/(moving?1:16),bz=z0+(z1-z0)*(zi+1)/(moving?1:16);double a=y0+(y1-y0)*i/32,b=y0+(y1-y0)*(i+1)/32;double[] lo={100,100,100},hi={-100,-100,-100};for(double x:new double[]{x0,x1})for(double y:new double[]{a,b})for(double z:new double[]{az,bz}){double[] q=point(w,x,y,z,moving,angle);for(int j=0;j<3;j++){lo[j]=Math.min(lo[j],q[j]);hi[j]=Math.max(hi[j],q[j]);}}addBox(out,new AxisAlignedBB(lo[0],lo[1],lo[2],hi[0],hi[1],hi[2]));}}
    private static void addBox(List<AxisAlignedBB> out,AxisAlignedBB b){double x=Math.max(0,b.minX),y=Math.max(0,b.minY),z=Math.max(0,b.minZ),xx=Math.min(1,b.maxX),yy=Math.min(1,b.maxY),zz=Math.min(1,b.maxZ);if(xx>x+1e-8&&yy>y+1e-8&&zz>z+1e-8)out.add(new AxisAlignedBB(x,y,z,xx,yy,zz));}
    static void add(List<RoofMeshes.Face> out,List<double[]> p,int detail){for(int axis=0;axis<3;axis++){p=clip(p,axis,0,true);p=clip(p,axis,1,false);}if(p.size()<3)return;for(int i=1;i<p.size()-1;i++){double[] a=p.get(0),b=p.get(i),c=p.get(i+1);double nx=(b[1]-a[1])*(c[2]-a[2])-(b[2]-a[2])*(c[1]-a[1]),ny=(b[2]-a[2])*(c[0]-a[0])-(b[0]-a[0])*(c[2]-a[2]),nz=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);if(nx*nx+ny*ny+nz*nz>1e-16)out.add(new RoofMeshes.Face(Arrays.asList(a,b,c),false,-1,RoofPart.WINDOW,0,detail));}}
    private static List<double[]> clip(List<double[]> p,int axis,double edge,boolean greater){if(p.isEmpty())return p;List<double[]> out=new ArrayList<>();double[] a=p.get(p.size()-1);boolean ai=greater?a[axis]>=edge-1e-9:a[axis]<=edge+1e-9;for(double[] b:p){boolean bi=greater?b[axis]>=edge-1e-9:b[axis]<=edge+1e-9;if(ai!=bi){double t=(edge-a[axis])/(b[axis]-a[axis]);double[] q=new double[a.length];for(int i=0;i<q.length;i++)q[i]=a[i]+t*(b[i]-a[i]);out.add(q);}if(bi)out.add(b);a=b;ai=bi;}return out;}
}
